<?php
require_once __DIR__.'/includes/auth.php';requireLogin();$uid=(int)$_SESSION['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$id=(int)($_POST['id']??0);$q=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?');$q->execute([$id,$uid]);redirect('notifications.php');}$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([$uid]);$rows=$q->fetchAll();$pageTitle='Notifications';require __DIR__.'/includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">UPDATES</p><h1>Notifications</h1><p>Subscription decisions, coaching updates and administrator messages.</p></div></section><section class="panel"><?php if(!$rows):?><p>You have no notifications.</p><?php endif;?><?php foreach($rows as $n):?><article class="notification-row"><div><strong><?=e($n['title'])?></strong><p><?=nl2br(e($n['message']))?></p><small><?=e($n['created_at'])?></small></div><?php if(!$n['is_read']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=(int)$n['id']?>"><button class="button light btn-small">Mark read</button></form><?php endif;?></article><?php endforeach;?></section><?php require __DIR__.'/includes/footer.php';?>
